<?php require_once __DIR__."/config.php"; require_login(); verify_csrf(); $id=(int)($_POST["id"]??0); $estado=(int)($_POST["estado"]??0); if(!in_array($estado,[0,1],true)){flash("danger","Estado no válido.");redirect("index.php");} $s=db()->prepare("UPDATE productos SET estado=? WHERE id_producto=?");$s->execute([$estado,$id]);flash("success",$estado?"Producto reactivado.":"Producto desactivado. Se conserva su historial de movimientos.");redirect("index.php");